(1, 'roses', 'Троянда плетиста «Воллертон Олд Хол»', 'Кремово-абрикосова, сильний аромат, до 3 м', 115, NULL, 1, 1, '["img/rose1.jpg"]', '["Плетиста англійська троянда з чашоподібними кремово-абрикосовими квітками та сильним ароматом.","Добре підходить для арок, пергол і стін будинку. Цвіте кілька разів за сезон."]', '[["Тип","плетиста"],["Висота","до 3 м"],["Колір","кремово-абрикосовий"],["Аромат","сильний"],["Цвітіння","повторне, червень–вересень"],["Місце","сонце або легка півтінь"]]', 1, '2026-11-09T13:37:41.794Z'),
(2, 'roses', 'Троянда «Джентл Герміона»', 'Англійська, ніжно-рожева, цвіте до морозів', 110, 125, 1, 1, '["img/rose3.jpg"]', '["Англійська кущова троянда з ніжно-рожевими чашоподібними квітками.","Цвіте хвилями від початку літа до морозів, гарна і на клумбі, і в зрізці."]', '[["Тип","англійська кущова"],["Висота","1–1,2 м"],["Колір","ніжно-рожевий"],["Аромат","виражений"],["Цвітіння","хвилями до морозів"],["Місце","сонце"]]', 2, '2026-11-09T13:37:41.795Z'),
(3, 'roses', 'Троянда чайно-гібридна «Піано»', 'Піоновидна, червона, для зрізу', 120, NULL, 1, 1, '["img/rose2.jpg"]', '["Чайно-гібридна троянда з густомахровими піоновидними квітками насиченого червоного кольору.","Квітки довго стоять у вазі, тому сорт часто вирощують для зрізу."]', '[["Тип","чайно-гібридна"],["Висота","0,8–1 м"],["Колір","червоний"],["Форма квітки","піоновидна"],["Цвітіння","повторне"],["Місце","сонце"]]', 3, '2026-11-09T13:37:41.795Z'),
(4, 'decor', 'Лаванда вузьколиста «Хідкот»', 'Морозостійка, для бордюрів і клумб', 90, NULL, 1, 1, '["img/lavender.jpg"]', '["Компактна лаванда з темно-фіолетовими суцвіттями та сріблястим листям.","Добре тримає форму, тому підходить для бордюрів, клумб і доріжок."]', '[["Висота","40–50 см"],["Колір","темно-фіолетовий"],["Цвітіння","червень–серпень"],["Зимівля","морозостійка"],["Місце","сонце, легкий ґрунт"]]', 4, '2026-11-09T13:37:41.795Z'),
(5, 'decor', 'Самшит вічнозелений, набір 10 шт', 'Для живоплоту, висота 15–20 см', 500, NULL, 1, 1, '["img/boxwood.jpg"]', '["Вічнозелений кущ із дрібним щільним листям, який легко формувати стрижкою.","Набору з 10 саджанців вистачає приблизно на 2–3 метри низького живоплоту."]', '[["У наборі","10 саджанців"],["Висота саджанців","15–20 см"],["Ріст","повільний"],["Листя","вічнозелене"],["Місце","сонце або тінь"]]', 5, '2026-11-09T13:37:41.795Z'),
(6, 'fruit', 'Яблуня «Чорний Принц»', 'Темно-бордові плоди, зимовий сорт', 150, NULL, 0, 1, '["img/apple.jpg"]', '["Зимовий сорт із незвичними темно-бордовими плодами.","Яблука добре зберігаються взимку. Для кращого врожаю посадіть поруч ще одну яблуню."]', '[["Термін дозрівання","зимовий"],["Колір плодів","темно-бордовий"],["Запилення","потрібен сорт-запилювач"],["Місце","сонце"]]', 6, '2026-11-09T13:37:41.795Z'),
(7, 'fruit', 'Яблуня «Джеромін»', 'Рання, солодка, дає врожай на 3-й рік', 145, NULL, 0, 1, '["img/blossom.jpg"]', '["Яблуня з темно-червоними солодкими плодами.","Починає плодоносити рано — перший врожай уже на 3-й рік після посадки."]', '[["Смак","солодкий"],["Перший врожай","на 3-й рік"],["Запилення","потрібен сорт-запилювач"],["Місце","сонце"]]', 7, '2026-11-09T13:37:41.795Z'),
(8, 'berries', 'Ожина «Потрійна корона»', 'Без колючок, великі солодкі ягоди', 140, 160, 0, 1, '["img/blackberry.jpg"]', '["Безколюча ожина з великими солодкими ягодами.","Пагони довгі, тому їх варто підв''язувати до шпалери."]', '[["Колючки","немає"],["Ягоди","великі, солодкі"],["Пагони","довгі, потрібна шпалера"],["Місце","сонце"]]', 8, '2026-11-09T13:37:41.795Z'),
(9, 'berries', 'Малина ремонтантна «Полька»', 'Плодоносить з липня до морозів', 85, NULL, 0, 1, '["img/raspberry.jpg"]', '["Ремонтантна малина, яка дає ягоди з липня до самих морозів.","Ягоди червоні, щільні, добре переносять перевезення."]', '[["Тип","ремонтантна"],["Плодоношення","липень — морози"],["Ягоди","червоні, щільні"],["Місце","сонце"]]', 9, '2026-11-09T13:37:41.795Z'),
(10, 'berries', 'Агрус «Командор»', 'Майже без шипів, стійкий до хвороб', 95, NULL, 0, 1, '["img/gooseberry.jpg"]', '["Агрус майже без шипів — збирати ягоди зручно і не боляче.","Сорт стійкий до хвороб і невибагливий у догляді."]', '[["Шипи","майже немає"],["Стійкість","до хвороб"],["Висота куща","до 1,2 м"],["Місце","сонце або легка півтінь"]]', 10, '2026-11-09T13:37:41.796Z'),
(11, 'strawberry', 'Полуниця «Альбіон», 5 розеток', 'Ремонтантна, плодоносить усе літо', 150, NULL, 0, 1, '["img/strawberry.jpg"]', '["Ремонтантна полуниця з великими щільними солодкими ягодами.","Плодоносить хвилями все літо. У наборі 5 розеток."]', '[["У наборі","5 розеток"],["Тип","ремонтантна"],["Плодоношення","усе літо"],["Ягоди","великі, щільні"],["Місце","сонце"]]', 11, '2026-11-09T13:37:41.796Z'),
(12, 'grapes', 'Виноград «Аркадія»', 'Столовий, ранній, грона до 1 кг', 130, NULL, 0, 1, '["img/grapes.jpg"]', '["Столовий виноград раннього строку достигання.","Формує великі грона — до 1 кг."]', '[["Тип","столовий"],["Достигання","ранній"],["Грона","до 1 кг"],["Місце","сонце, біля опори"]]', 12, '2026-11-09T13:37:41.796Z'),
(13, 'nuts', 'Горіх грецький «Ідеал»', 'Скороплідний, перші горіхи на 2–3 рік', 220, NULL, 0, 1, '["img/walnut.jpg"]', '["Скороплідний сорт грецького горіха.","Перші горіхи з''являються вже на 2–3 рік після посадки."]', '[["Перший врожай","на 2–3 рік"],["Місце","сонце, простір для крони"]]', 13, '2026-11-09T13:37:41.796Z'),
(14, 'exotic', 'Інжир «Брунсвік»', 'Витримує до −25 °C з укриттям', 240, NULL, 0, 1, '["img/fig.jpg"]', '["Один із найвитриваліших сортів інжиру для нашого клімату.","З укриттям витримує морози до −25 °C."]', '[["Зимівля","до −25 °C з укриттям"],["Місце","сонце, захищене від вітру"]]', 14, '2026-11-09T13:37:41.796Z');
